<?php $maxTraffic=1;foreach($traffic as $row){$maxTraffic=max($maxTraffic,(int)$row['bytes_in']+(int)$row['bytes_out']);} ?>
<div class="page-head"><div><a class="back-link" href="<?= e(url('users')) ?>">→ <?= e(tr('بازگشت به کاربران','Back to users')) ?></a><div class="title-with-status"><h1 dir="ltr"><?= e($user['username']) ?></h1><span class="badge <?= $session?'success':'muted' ?>"><?= e($session?tr('آنلاین','Online'):tr('آفلاین','Offline')) ?></span></div><p><?= e($user['full_name']?:tr('بدون نام ثبت‌شده','No name recorded')) ?></p></div><?php if(Auth::canWrite()):?><div class="head-actions"><a class="button ghost" href="<?= e(url('user-form',['id'=>$user['id']])) ?>"><?= e(tr('ویرایش','Edit')) ?></a><form method="post" action="<?= e(url('user-toggle')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($user['id']) ?>"><button class="button warning"><?= e($user['status']==='active'?tr('غیرفعال‌کردن','Disable'):tr('فعال‌کردن','Enable')) ?></button></form><form method="post" action="<?= e(url('user-renew')) ?>" data-confirm="<?= e(tr('کاربر تمدید و فاکتور جدید ساخته شود؟','Renew the user and create a new invoice?')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($user['id']) ?>"><button class="button success-button">↻ <?= e(tr('تمدید','Renew')) ?></button></form></div><?php endif;?></div>
