<div class="content-grid half">
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('مشخصات مشترک','Subscriber details')) ?></h2></div></div><dl class="detail-list"><div><dt><?= e(tr('روتر','Router')) ?></dt><dd><?= e($user['router_name']) ?></dd></div><div><dt><?= e(tr('سرویس','Service')) ?></dt><dd><?= e(strtoupper($user['service'])) ?></dd></div><div><dt><?= e(tr('تلفن','Phone')) ?></dt><dd dir="ltr"><?= e($user['phone']?:'—') ?></dd></div><div><dt><?= e(tr('آدرس','Address')) ?></dt><dd><?= e($user['address']?:'—') ?></dd></div><div><dt><?= e(tr('آخرین همگام‌سازی','Last sync')) ?></dt><dd><?= e($user['last_synced_at']?:'—') ?></dd></div><div><dt><?= e(tr('یادداشت','Comment')) ?></dt><dd><?= nl2br(e($user['comment']?:'—')) ?></dd></div></dl></section>
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('نشست جاری','Current session')) ?></h2><p><?= e(tr('اطلاعات آخرین پایش روتر','Latest router poll data')) ?></p></div></div><?php if($session):?><div class="session-hero"><span class="pulse"></span><strong><?= e(tr('متصل است','Connected')) ?></strong><small><?= e($session['last_seen_at']) ?></small></div><dl class="detail-list compact"><div><dt>IP</dt><dd dir="ltr"><?= e($session['address']?:'—') ?></dd></div><div><dt><?= e(tr('زمان اتصال','Uptime')) ?></dt><dd dir="ltr"><?= e($session['uptime']?:'—') ?></dd></div><div><dt><?= e(tr('دانلود نشست','Session download')) ?></dt><dd><?= fa_digits(number_format($session['bytes_in']/1e9,3)) ?> GB</dd></div><div><dt><?= e(tr('آپلود نشست','Session upload')) ?></dt><dd><?= fa_digits(number_format($session['bytes_out']/1e9,3)) ?> GB</dd></div></dl><?php else:?><div class="empty-state compact-empty"><span>⌁</span><p><?= e(tr('در آخرین ۱۵ دقیقه نشست فعالی دیده نشده است.','No active session was seen in the last 15 minutes.')) ?></p></div><?php endif;?></section>
</div>
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('ترافیک ۳۰ روز اخیر','Traffic — last 30 days')) ?></h2><p><?= e(tr('آبی: دانلود، سبز: آپلود','Blue: download, green: upload')) ?></p></div></div><div class="traffic-chart"><?php foreach($traffic as $row):$inPct=max(1,(int)round(((int)$row['bytes_in']/$maxTraffic)*100));$outPct=max(1,(int)round(((int)$row['bytes_out']/$maxTraffic)*100));?><div class="chart-column" title="<?= e($row['log_date'].' · '.number_format($row['bytes_in']/1e9,3).' / '.number_format($row['bytes_out']/1e9,3).' GB') ?>"><div class="bars"><i class="in" style="height:<?= $inPct ?>%"></i><i class="out" style="height:<?= $outPct ?>%"></i></div><small><?= e(substr($row['log_date'],5)) ?></small></div><?php endforeach;?><?php if(!$traffic):?><p class="empty"><?= e(tr('هنوز داده ترافیکی ثبت نشده است. Cron را فعال کنید.','No traffic data yet. Enable the cron job.')) ?></p><?php endif;?></div></section>
<section class="panel"><div class="panel-head"><div><h2><?= e(tr('صورتحساب‌های کاربر','User invoices')) ?></h2></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th><?= e(tr('مبلغ','Amount')) ?></th><th><?= e(tr('پرداخت‌شده','Paid')) ?></th><th><?= e(tr('وضعیت','Status')) ?></th><th><?= e(tr('سررسید','Due')) ?></th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><a href="<?= e(url('invoice-detail',['id'=>$invoice['id']])) ?>" dir="ltr"><?= e($invoice['invoice_number']) ?></a></td><td><?= money($invoice['total'],$user['currency']?:'IRR') ?></td><td><?= money($invoice['paid_amount'],$user['currency']?:'IRR') ?></td><td><span class="badge <?= badge_class($invoice['status']) ?>"><?= e(status_text($invoice['status'])) ?></span></td><td><?= e($invoice['due_date']) ?></td></tr><?php endforeach;?><?php if(!$invoices):?><tr><td colspan="5" class="empty"><?= e(tr('فاکتوری ثبت نشده است.','No invoices found.')) ?></td></tr><?php endif;?></tbody></table></div></section>
